import { subscribeFeed } from "./subscription.js";
import { presentBatch } from "./batch-presenter.js";

export function createFeedPanel({ history, paintRows, showCount }) {
  let current = null;
  let request = 0;

  const retire = visit => {
    if (!visit) return;
    const release = visit.release;
    visit.release = () => {};
    release();
  };

  return {
    show(feed, mode = "synchronous") {
      const requested = ++request;
      const previous = current;
      current = null;
      retire(previous);
      if (request !== requested) return;

      const visit = { release: () => {} };
      const isCurrent = () => current === visit;
      current = visit;
      const release = subscribeFeed(feed, mode, frame => {
        if (isCurrent())
          presentBatch(frame, { paintRows, showCount, isCurrent });
      }, history, isCurrent);

      if (isCurrent()) visit.release = release;
      else release();
    },
    close() {
      ++request;
      const previous = current;
      current = null;
      retire(previous);
    },
  };
}

